import {fields,bodyFields,folds,days} from './calculations.js';
import {emptyPreferences,today,goalStatus,unusualChanges,validDate} from './experience-model.js';
const $=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n),date=s=>s?.split('-').reverse().join('/')||'—';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const option=(value,label)=>`<option value="${esc(value)}">${esc(label)}</option>`;
const training={rest:'Sem treino recente',before:'Antes do treino',after:'Depois do treino'};
export function contextLabel(r){const c=r?.context;if(!c)return '';return [c.time,training[c.training],c.conditions].filter(Boolean).join(' · ');}
export function mountExperience({getRecords,isDemo,request,openForm,message,redrawChart}){
  let preferences=emptyPreferences(),revision=0,epoch=0,active='summary',saving=false,photoEpoch=0,photos=[];
  const tabs=[['summary','Resumo'],['measures','Medidas'],['composition','Composição'],['history','Histórico'],['plan','Metas'],['photos','Fotos'],['guide','Como medir']];
  const tabBar=document.createElement('div');tabBar.className='workspace-tabs';tabBar.setAttribute('role','tablist');tabBar.setAttribute('aria-label','Seções do acompanhamento');
  tabBar.innerHTML=tabs.map(([id,label])=>`<button type="button" role="tab" id="tab-${id}" aria-controls="view-${id}" aria-selected="${id===active}" tabindex="${id===active?0:-1}" data-tab="${id}">${label}</button>`).join('');
  $('.period').before(tabBar);
  const panels={};for(const [id] of tabs){const el=document.createElement('section');el.id='view-'+id;el.setAttribute('role','tabpanel');el.setAttribute('aria-labelledby','tab-'+id);el.hidden=id!==active;el.className='workspace-view';$('footer').before(el);panels[id]=el;}
  for(const [tab,selectors] of Object.entries({summary:['#cards','#evolution'],measures:['#comparison'],composition:['#composition-changes','#body-progress','#composition'],history:['#history']}))for(const selector of selectors)panels[tab].append($(selector));
  const headline=document.createElement('section');headline.id='journey-overview';headline.className='journey-overview';$('.heading').after(headline);
  const reportButton=document.createElement('button');reportButton.id='print-report';reportButton.className='quiet';reportButton.textContent='↓ Relatório / PDF';$('header').append(reportButton);
  const report=document.createElement('article');report.id='print-content';report.hidden=true;document.body.append(report);
  const state=document.createElement('p');state.id='workspace-status';state.setAttribute('role','status');state.className='workspace-status';tabBar.after(state);
  function setTab(id,focus=false){if(!panels[id])return;active=id;$('.period').hidden=['plan','photos','guide'].includes(id);headline.hidden=id!=='summary';$('#welcome').hidden=id!=='summary'||getRecords().length>0;for(const [key,panel] of Object.entries(panels))panel.hidden=key!==id;for(const b of tabBar.querySelectorAll('button')){b.setAttribute('aria-selected',String(b.dataset.tab===id));b.tabIndex=b.dataset.tab===id?0:-1;}if(focus)$('#tab-'+id).focus();if(id==='photos')void loadPhotos();else clearPhotoViews();if(id==='summary')redrawChart();document.querySelectorAll('aside nav a').forEach(a=>{const target=navMap[a.hash];a.classList.toggle('active',target===id);if(target===id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
  tabBar.onclick=e=>{const button=e.target.closest('[data-tab]');if(button)setTab(button.dataset.tab);};
  tabBar.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let i=tabs.findIndex(([id])=>id===active);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setTab(tabs[i][0],true);};
  const measureNav=$('aside nav a[href="#evolution"]');measureNav.href='#comparison';measureNav.textContent='↗　Medidas';
  const navMap={'#overview':'summary','#comparison':'measures','#body-progress':'composition','#history':'history'};
  document.querySelectorAll('aside nav a').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();setTab(navMap[a.hash]);tabBar.scrollIntoView({block:'start'});}));
  // Period filtering and an explicit, touch-accessible chart readout.
  const controls=document.createElement('div');controls.className='chart-controls';controls.innerHTML='<label>Pontos exibidos <select id="chart-range"><option value="all">Todo o histórico</option><option value="90">Últimos 90 dias do histórico</option><option value="30">Últimos 30 dias do histórico</option><option value="selected">Comparação selecionada</option></select></label><label>Avaliação no gráfico<select id="chart-point" aria-label="Consultar avaliação no gráfico"></select></label><output id="chart-readout" aria-live="polite">Toque em um ponto para consultar a avaliação.</output>';
  $('#chart').before(controls);$('#chart-range').onchange=redrawChart;$('#chart-point').onchange=()=>{const index=Number($('#chart-point').value);const points=[...$('#chart').querySelectorAll('circle')];points.forEach((p,i)=>p.classList.toggle('selected-chart-point',i===index));$('#chart-readout').textContent=$('#chart-point').selectedOptions[0]?.textContent||'Sem pontos neste período.';};
  for(const event of ['click','focusin'])$('#chart').addEventListener(event,e=>{const point=e.target.closest('circle');if(point){$('#chart-readout').textContent=point.getAttribute('aria-label');const points=[...$('#chart').querySelectorAll('circle')];$('#chart-point').value=String(points.indexOf(point));points.forEach(p=>p.classList.toggle('selected-chart-point',p===point));}});
  $('#chart').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('circle')){e.preventDefault();$('#chart-readout').textContent=e.target.getAttribute('aria-label');}});
  const regionGroups={arms:['Braços',['armRelaxedRight','armRelaxedLeft','armFlexedRight','armFlexedLeft','forearmRight','forearmLeft']],torso:['Tronco',['chest','waist','abdomen','hip']],legs:['Pernas',['thighRight','thighLeft','calfRight','calfLeft']]};
  let selectedRegion='arms';
  buildPlan();buildGuide();panels.guide.append($('.research'));buildRegions();buildPhotos();const wizard=buildWizard();
  function status(text){state.textContent=text;}
  async function load(){const token=++epoch;preferences=emptyPreferences();revision=0;refresh();try{const result=await request('/api/preferences');if(token!==epoch)return;preferences=result.preferences;revision=result.revision;status('');refresh();}catch(error){if(token===epoch)status('Metas e lembretes indisponíveis: '+error.message);} }
  async function savePreferences(next){if(isDemo()){status('Saia do exemplo para salvar metas ou lembretes.');return false;}if(saving){status('Aguarde a gravação anterior terminar.');return false;}const token=epoch;saving=true;try{const result=await request('/api/preferences',{method:'PUT',body:JSON.stringify({preferences:next,revision})});if(token!==epoch)return false;preferences=result.preferences;revision=result.revision;refresh();status('Preferências salvas na sua conta.');return true;}catch(error){if(token===epoch)status(error.message);return false;}finally{if(token===epoch)saving=false;}}
  function refresh(){const records=getRecords(),last=records.at(-1);$('#welcome').hidden=active!=='summary'||records.length>0;headline.innerHTML=`<div><span class="eyebrow">${isDemo()?'EXEMPLO ILUSTRATIVO':'SEU PRÓXIMO PASSO'}</span><h2>${last?'Continue construindo seu histórico.':'Tudo começa com uma avaliação.'}</h2><p>${last?`${records.length} avaliação(ões) · Último registro em ${date(last.date)}.`:'Registre o que você mediu. Complete o restante quando quiser.'}</p></div><div class="journey-action"><span>${!isDemo()&&preferences.reminder?`Próxima avaliação: ${date(preferences.reminder)}${preferences.reminder<today()?' · data passou':preferences.reminder===today()?' · hoje':''}`:'Uma comparação de cada vez, no seu ritmo.'}</span><button id="quick-assessment" class="primary">${last?'Registrar próxima avaliação':'Começar meu histórico'} ↗</button></div>`;$('#quick-assessment').onclick=()=>openForm();renderGoals();renderRegion();if(active==='summary')redrawChart();}
  function buildPlan(){panels.plan.innerHTML=`<section class="panel"><p class="eyebrow">DIREÇÃO, SEM PRESSÃO</p><h2>Metas que fazem sentido para você.</h2><p class="muted">Defina até seis metas pessoais. A barra mostra o caminho entre o valor de referência e o desejado; não avalia sua saúde nem prevê um resultado.</p><div id="goal-list" class="goal-grid"></div><details><summary>＋ Criar uma meta</summary><form id="goal-form" class="planning-form"><label>Medida<select name="metric">${Object.entries(fields).map(([k,[n,u]])=>option(k,n+' ('+u+')')).join('')}</select></label><label>Valor desejado<input name="target" inputmode="decimal" required placeholder="Ex.: 80,5"></label><label>Data desejada<input name="deadline" type="date" required></label><button class="primary">Salvar meta</button></form></details></section><section class="panel"><p class="eyebrow">PRÓXIMA AVALIAÇÃO</p><h2>Um lembrete no seu dashboard.</h2><p class="muted">Opcional. Aparece quando você abre o Forma; não envia e-mails ou notificações com o site fechado.</p><form id="reminder-form" class="planning-form"><label>Quando quer medir novamente?<input type="date" name="reminder"></label><button class="primary">Salvar lembrete</button><button type="button" class="quiet" id="clear-reminder">Desativar</button></form></section>`;
    $('#goal-form').onsubmit=async e=>{e.preventDefault();const f=e.target,raw=f.elements.target.value.trim().replace(',','.');if(!/^\d+(\.\d+)?$/.test(raw)||Number(raw)<=0||f.elements.metric.value==='fat'&&Number(raw)>=100)return status('Informe um valor positivo; BF deve ser menor que 100%.');if(preferences.goals.length>=6)return status('Você já tem seis metas. Remova uma para criar outra.');if(!validDate(f.elements.deadline.value)||f.elements.deadline.value<today())return status('Escolha uma data a partir de hoje.');const metric=f.elements.metric.value,last=[...getRecords()].reverse().find(r=>Number.isFinite(r[metric]));const goal={id:crypto.randomUUID(),metric,target:Number(raw),date:f.elements.deadline.value,startDate:last?.date&&last.date<=today()?last.date:today(),baseline:last?.[metric]??null};if(await savePreferences({...preferences,goals:[...preferences.goals,goal]}))f.reset();};
    $('#goal-list').onclick=async e=>{const b=e.target.closest('[data-remove-goal]');if(b&&confirm('Remover esta meta? Suas avaliações serão preservadas.'))await savePreferences({...preferences,goals:preferences.goals.filter(g=>g.id!==b.dataset.removeGoal)});};
    $('#reminder-form').onsubmit=e=>{e.preventDefault();const value=e.target.elements.reminder.value;if(value&&!validDate(value))return status('Confira a data.');void savePreferences({...preferences,reminder:value||null});};$('#clear-reminder').onclick=()=>void savePreferences({...preferences,reminder:null});
  }
  function renderGoals(){$('#reminder-form').elements.reminder.value=preferences.reminder||'';$('#goal-list').innerHTML=isDemo()?'<p class="empty">Metas pessoais ficam disponíveis fora do modo de exemplo.</p>':preferences.goals.length?preferences.goals.map(g=>{const s=goalStatus(g,getRecords()),[name,unit]=fields[g.metric];return `<article class="goal-card"><span class="pill">ATÉ ${date(g.date)}</span><h3>${name}</h3><strong>${fmt(g.target)} ${unit}</strong><p>${s?`Último valor: ${fmt(s.value)} ${unit} (${date(s.date)}) · Distância até o alvo: ${fmt(Math.abs(s.distance))} ${unit}.`:'Registre esta medida para acompanhar a meta.'}</p>${s?.progress!=null?`<progress max="100" value="${s.progress}" aria-label="Progresso da meta de ${name}"></progress><small>${fmt(s.progress)}% do caminho entre referência e alvo.</small>`:''}<button type="button" class="quiet" data-remove-goal="${esc(g.id)}">Remover meta</button></article>`;}).join(''):'<p class="empty">Escolha uma medida que você deseja acompanhar. Não é preciso definir uma meta para usar o Forma.</p>';}
  function buildGuide(){panels.guide.innerHTML=`<section class="panel"><p class="eyebrow">MENOS DÚVIDAS, MAIS CONSISTÊNCIA</p><h2>Prepare sua próxima medição.</h2><div class="guide-layout"><svg viewBox="0 0 240 400" role="img" aria-label="Ilustração esquemática: fita ao redor da cintura, braço e panturrilha"><circle cx="120" cy="45" r="24"/><path d="M100 76 Q65 76 60 105 L36 202 L54 208 L81 141 L82 216 L74 358 L102 358 L120 245 L138 358 L166 358 L158 216 L159 141 L186 208 L204 202 L180 105 Q175 76 140 76Z"/><g class="guide-tape"><path d="M80 182H160M59 126L78 133M77 302H108"/></g><text x="167" y="185">Cintura</text><text x="8" y="120">Braço</text><text x="112" y="308">Panturrilha</text></svg><div><h3>Fita nivelada, sem apertar</h3><p>Use uma fita flexível e não elástica. Mantenha contato com a pele sem comprimir. Repita o mesmo ponto, lado e posição em todas as avaliações.</p><h3>Condições parecidas</h3><p>Registre horário, treino recente e qualquer condição diferente. Use a mesma balança e anote as medidas em cm, o peso em kg e as dobras em mm.</p><h3>Direito e esquerdo são registros diferentes</h3><p>Não copie um lado para o outro. Braço relaxado e contraído também precisam de campos separados. Se não mediu, deixe em branco.</p></div></div><details open><summary>Cintura, braços e pernas</summary><p><strong>Cintura:</strong> o protocolo do CDC usa a fita horizontal logo acima dos ossos do quadril, com o abdômen relaxado após uma expiração normal. Outros protocolos usam pontos diferentes: registre o seu e mantenha-o.</p><p><strong>Braço relaxado:</strong> padronize o ponto com seu avaliador; protocolos antropométricos usam um ponto médio marcado no braço. Para a medida contraída, registre a posição adotada e mantenha-a nas próximas avaliações.</p><p><strong>Antebraço, tórax, quadril, coxa e panturrilha:</strong> combine os pontos e posições com seu avaliador e descreva-os no contexto. A ilustração orienta a leitura, não define pontos anatômicos com precisão.</p></details><details><summary>Dobras cutâneas</summary><p>São espessuras em milímetros, não percentuais locais de gordura. O protocolo de sete dobras exige peitoral, axilar média, tricipital, subescapular, abdominal, suprailíaca e coxa. Peça a uma pessoa capacitada para marcar e medir os pontos; esta ilustração não ensina a técnica de adipometria.</p></details><p class="muted">Referências: <a href="https://www.cdc.gov/diabetes/living-with/healthy-weight.html" target="_blank" rel="noopener">CDC · cintura</a> e <a href="https://wwwn.cdc.gov/nchs/data/nhanes/public/2011/manuals/anthropometry_procedures_manual.pdf" target="_blank" rel="noopener">manual de antropometria NHANES</a>.</p></section>`;}
  function buildRegions(){const el=document.createElement('section');el.className='panel';el.innerHTML=`<div class="panel-head"><div><p class="eyebrow">EXPLORE SUAS MEDIDAS</p><h2>Uma região de cada vez.</h2></div></div><div class="region-explorer"><svg id="measure-body" viewBox="0 0 240 380" role="group" aria-label="Escolha uma região do corpo"><circle cx="120" cy="36" r="24" class="figure-head"/><g role="button" tabindex="0" data-body-region="arms" aria-label="Braços e antebraços"><path d="M85 77L59 87L30 209L51 217L87 132ZM155 77L181 87L210 209L189 217L153 132Z"/></g><g role="button" tabindex="0" data-body-region="torso" aria-label="Tronco"><path d="M91 73H149L158 151L151 216H89L82 151Z"/></g><g role="button" tabindex="0" data-body-region="legs" aria-label="Coxas e panturrilhas"><path d="M89 222H116L111 354H78ZM124 222H151L162 354H129Z"/></g></svg><div><div class="region-switch">${Object.entries(regionGroups).map(([k,[label]])=>`<button class="quiet" data-body-region="${k}" type="button">${label}</button>`).join('')}</div><div id="measure-region-result"></div></div></div><p class="muted">Diferenças entre lados são descritivas, não um diagnóstico de assimetria. Compare sempre a mesma condição do braço.</p></section>`;panels.measures.prepend(el);el.onclick=e=>{const b=e.target.closest('[data-body-region]');if(b){selectedRegion=b.dataset.bodyRegion;renderRegion();}};el.onkeydown=e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('g[data-body-region]')){e.preventDefault();selectedRegion=e.target.dataset.bodyRegion;renderRegion();}};}
  function renderRegion(){if(!$('#measure-region-result'))return;const records=getRecords(),a=records.find(r=>r.id===$('#from').value),b=records.find(r=>r.id===$('#to').value),[label,keys]=regionGroups[selectedRegion];document.querySelectorAll('[data-body-region]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.bodyRegion===selectedRegion)));$('#measure-region-result').innerHTML=`<h3>${label}</h3><div class="region-measure-list">${keys.map(k=>{const values=records.filter(r=>Number.isFinite(r[k])),v=values.map(r=>r[k]),lo=Math.min(...v),hi=Math.max(...v);const pts=values.map((r,i)=>`${10+i/Math.max(1,values.length-1)*170},${45-(r[k]-lo)/(hi-lo||1)*30}`).join(' ');const diff=a?.[k]!=null&&b?.[k]!=null&&a.date<b.date?b[k]-a[k]:null;return `<div><span>${fields[k][0]}</span><strong>${b?.[k]!=null?fmt(b[k])+' cm':'—'}</strong><small>${diff!=null?`${diff>0?'+':''}${fmt(diff)} cm no período`:'Sem comparação'}</small>${values.length?`<svg viewBox="0 0 190 60" role="img" aria-label="Histórico de ${fields[k][0]}: ${values.map(r=>date(r.date)+': '+fmt(r[k])+' cm').join('; ')}"><polyline points="${pts}" fill="none" stroke="currentColor" stroke-width="2"/>${values.map((r,i)=>`<circle cx="${10+i/Math.max(1,values.length-1)*170}" cy="${45-(r[k]-lo)/(hi-lo||1)*30}" r="3"><title>${date(r.date)}: ${fmt(r[k])} cm</title></circle>`).join('')}</svg><small>${date(values[0].date)} → ${date(values.at(-1).date)} · Registros em sequência</small>`:''}</div>`;}).join('')}</div>${keys.filter(k=>k.endsWith('Right')&&b?.[k]!=null&&b?.[k.replace('Right','Left')]!=null).map(k=>`<p class="side-difference">${fields[k][0].replace(' direito','')}: direito − esquerdo = ${fmt(b[k]-b[k.replace('Right','Left')])} cm.</p>`).join('')}`;}
  function buildWizard(){const form=$('#form'),body=$('#inputs');const steps=[];const intro=document.createElement('div');intro.className='wizard-page';body.before(intro);intro.append(form.elements.date.closest('label'));const generals=Object.keys(bodyFields).slice(0,2);for(const k of generals)intro.append(form.elements[k].closest('label'));steps.push(intro);
    const titles=['Dados gerais','Tronco','Braços','Pernas','Dobras e contexto'];for(const keys of [Object.keys(bodyFields).slice(2,8),Object.keys(bodyFields).slice(8,14),Object.keys(bodyFields).slice(14)]){const step=document.createElement('div');step.className='wizard-page form-grid';body.before(step);for(const k of keys)step.append(form.elements[k].closest('label'));steps.push(step);}body.hidden=true;const end=document.createElement('div');end.className='wizard-page';$('.fold-section').before(end);end.append($('.fold-section'));end.append(form.elements.notes.closest('label'));const context=document.createElement('div');context.className='form-grid';context.innerHTML='<label>Horário da medição<input name="contextTime" type="time"></label><label>Treino recente<select name="contextTraining"><option value="">Não informado</option><option value="rest">Sem treino recente</option><option value="before">Antes do treino</option><option value="after">Depois do treino</option></select></label><label class="full-field">Condições da medição<textarea name="contextConditions" maxlength="300" placeholder="Ex.: mesma balança, antes do café, hidratação habitual, ponto usado na cintura…"></textarea></label>';end.prepend(context);steps.push(end);
    const controls=document.createElement('div');controls.className='wizard-controls';controls.innerHTML=`<div class="wizard-steps">${titles.map((title,i)=>`<button type="button" data-step="${i}">${i+1}. ${title}</button>`).join('')}</div><div class="wizard-tools"><output id="wizard-progress"></output><button type="button" class="quiet" id="wizard-all">Mostrar todos os campos</button><button type="button" class="quiet" id="open-guide">Guia de medição ↗</button></div>`;form.querySelector('.panel-head').after(controls);
    const actions=document.createElement('div');actions.className='wizard-actions';actions.innerHTML='<button type="button" class="quiet" id="wizard-back">← Voltar</button><span>Campos não medidos podem ficar em branco.</span><button type="button" class="primary" id="wizard-next">Próxima etapa →</button>';$('#form-error').before(actions);let step=0,all=false;
    function show(i){step=Math.max(0,Math.min(4,i));steps.forEach((el,n)=>el.hidden=!all&&step!==n);controls.querySelectorAll('[data-step]').forEach(b=>{b.setAttribute('aria-current',Number(b.dataset.step)===step&&!all?'step':'false');});$('#wizard-back').disabled=all||step===0;$('#wizard-next').disabled=all||step===4;$('#wizard-all').textContent=all?'Voltar às etapas':'Mostrar todos os campos';updateCount();}
    function updateCount(){const count=Object.keys(fields).filter(k=>form.elements[k]?.value.trim()).length;$('#wizard-progress').textContent=`${all?'Todos os campos':'Etapa '+(step+1)+' de 5'} · ${count} medidas preenchidas`;}
    controls.onclick=e=>{const b=e.target.closest('[data-step]');if(b){all=false;show(Number(b.dataset.step));}};$('#wizard-next').onclick=()=>show(step+1);$('#wizard-back').onclick=()=>show(step-1);$('#wizard-all').onclick=()=>{all=!all;show(step);};$('#open-guide').onclick=()=>{$('#dialog').close();setTab('guide');status('O formulário continua preenchido.');const b=document.createElement('button');b.className='quiet';b.textContent='Voltar à avaliação';b.onclick=()=>{$('#dialog').showModal();status('');};state.append(b);};form.addEventListener('input',updateCount);
    form.addEventListener('invalid',e=>{const page=e.target.closest('.wizard-page');if(page){all=false;show(steps.indexOf(page));}},{capture:true});
    return {open(record){all=false;form.elements.contextTime.value=record?.context?.time||'';form.elements.contextTraining.value=record?.context?.training||'';form.elements.contextConditions.value=record?.context?.conditions||'';show(0);},context(){const c={time:form.elements.contextTime.value,training:form.elements.contextTraining.value,conditions:form.elements.contextConditions.value.trim()};return Object.values(c).some(Boolean)?c:undefined;}};
  }
  function clearPhotoViews(){photoEpoch++;document.querySelectorAll('.photo-frame img').forEach(img=>img.remove());}
  function buildPhotos(){panels.photos.innerHTML=`<section class="panel"><div class="panel-head"><div><p class="eyebrow">SÓ NA SUA CONTA</p><h2>Fotos que contam sua história.</h2></div><span class="pill">ACESSO PRIVADO</span></div><p class="muted">Use a mesma distância, iluminação e postura. Enquadre da cabeça aos pés e escolha frente, lado ou costas. As imagens não são usadas para estimar gordura ou músculos.</p><form id="photo-form" class="planning-form"><label>Data<input name="date" type="date" required></label><label>Vista<select name="view"><option value="front">Frente</option><option value="side">Lado</option><option value="back">Costas</option></select></label><label>Imagem JPEG, PNG ou WebP<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></label><button class="primary">Guardar foto privada</button></form><p class="muted">Até 40 fotos por conta. Cada envio é convertido para JPEG, com até 1 MB, removendo metadados do arquivo. Fotos não entram no backup JSON nem no relatório.</p><p id="photo-status" role="status"></p><div class="photo-compare">${['a','b'].map(k=>`<div><label for="photo-${k}">${k==='a'?'Foto inicial':'Foto final'}</label><select id="photo-${k}"></select><div class="photo-frame" id="frame-${k}"><span>Selecione uma foto</span></div><button class="quiet" type="button" data-delete-photo="${k}">Excluir esta foto</button><button class="quiet" type="button" data-download-photo="${k}">Baixar foto</button></div>`).join('')}</div><p id="photo-compare-note" class="muted"></p></section>`;$('#photo-form').elements.date.value=today();
    $('#photo-form').onsubmit=async e=>{e.preventDefault();if(isDemo())return photoStatus('Saia do exemplo para enviar fotos.');const f=e.target,button=f.querySelector('button'),token=epoch;button.disabled=true;try{if(photos.length>=40)throw Error('Limite de 40 fotos. Exclua uma antes de enviar outra.');if(!validDate(f.elements.date.value))throw Error('Confira a data.');const data=await imageData(f.elements.photo.files[0]);if(token!==epoch)return;await request('/api/photos',{method:'POST',body:JSON.stringify({name:`${f.elements.date.value}_${f.elements.view.value}_${crypto.randomUUID()}.jpg`,data})});if(token!==epoch)return;f.elements.photo.value='';photoStatus('Foto salva na sua conta.');await loadPhotos();}catch(error){if(token===epoch)photoStatus(error.message);}finally{button.disabled=false;}};
    for(const k of ['a','b'])$('#photo-'+k).onchange=()=>void showPhotos();
    panels.photos.addEventListener('click',async e=>{const b=e.target.closest('[data-delete-photo],[data-download-photo]');if(!b)return;const k=b.dataset.deletePhoto||b.dataset.downloadPhoto,name=$('#photo-'+k).value;if(!name)return;const token=epoch;b.disabled=true;try{if(b.dataset.deletePhoto){if(!confirm('Excluir esta foto da sua conta? Esta ação não pode ser desfeita.'))return;await request('/api/photos/remove',{method:'POST',body:JSON.stringify({name})});if(token===epoch)await loadPhotos();}else{const {url}=await request('/api/photos/read',{method:'POST',body:JSON.stringify({name})});let blob;if(url.startsWith('data:image/jpeg;base64,')){blob=new Blob([Uint8Array.from(atob(url.split(',')[1]),c=>c.charCodeAt(0))],{type:'image/jpeg'});}else{const response=await fetch(url);if(!response.ok)throw Error('Não foi possível baixar a foto.');blob=await response.blob();}if(token===epoch)downloadBlob(blob,name);}}catch(error){if(token===epoch)photoStatus(error.message);}finally{b.disabled=false;}});
  }
  function photoStatus(text){$('#photo-status').textContent=text;}
  async function loadPhotos(){if(isDemo()){clearPhotoViews();photos=[];for(const k of ['a','b'])$('#photo-'+k).innerHTML=option('','Fotos indisponíveis no exemplo');return photoStatus('Saia do exemplo para acessar suas fotos privadas.');}const token=epoch;try{const result=await request('/api/photos');if(token!==epoch||active!=='photos')return;photos=result.photos;for(const k of ['a','b']){const select=$('#photo-'+k),old=select.value;select.innerHTML=option('','Selecione uma foto')+photos.map(p=>option(p.name,date(p.name.slice(0,10))+' · '+({front:'Frente',side:'Lado',back:'Costas'}[p.name.split('_')[1]]))).join('');select.value=photos.some(p=>p.name===old)?old:(k==='a'?photos[0]?.name:photos.at(-1)?.name)||'';}photoStatus(photos.length?`${photos.length} foto(s) privada(s).`:'Sua galeria está vazia. Envie sua primeira foto.');await showPhotos();}catch(error){if(token===epoch)photoStatus('Fotos indisponíveis: '+error.message);}}
  async function showPhotos(){clearPhotoViews();const token=photoEpoch;$('#photo-compare-note').textContent='';await Promise.all(['a','b'].map(async k=>{const name=$('#photo-'+k).value,frame=$('#frame-'+k);frame.replaceChildren();if(!name){frame.textContent='Selecione uma foto';return;}frame.textContent='Carregando foto privada…';try{const result=await request('/api/photos/read',{method:'POST',body:JSON.stringify({name})});if(token!==photoEpoch)return;const img=document.createElement('img');img.alt=`Foto ${date(name.slice(0,10))}, vista ${name.split('_')[1]}`;img.src=result.url;img.onerror=()=>{if(token===photoEpoch)frame.textContent='Foto indisponível. Selecione novamente para tentar.';};frame.replaceChildren(img);}catch(error){if(token===photoEpoch)frame.textContent=error.message;}}));const a=$('#photo-a').value,b=$('#photo-b').value;if(a&&b)$('#photo-compare-note').textContent=a===b?'Você está exibindo a mesma foto nos dois lados.':a.split('_')[1]!==b.split('_')[1]?'Vistas diferentes: escolha o mesmo ângulo para comparar.':a.slice(0,10)>b.slice(0,10)?'A foto inicial é mais recente que a final.':'Observe postura e iluminação antes de interpretar diferenças.';}
  reportButton.onclick=()=>{const a=getRecords().find(r=>r.id===$('#from').value),b=getRecords().find(r=>r.id===$('#to').value);if(!a||!b||a.date>b.date){message('Escolha um período válido antes de gerar o relatório.');return;}report.innerHTML=`<h1>forma · Relatório de evolução</h1><p>${isDemo()?'DADOS FICTÍCIOS · ':''}Período: ${date(a.date)} a ${date(b.date)} · Emitido em ${date(today())}</p>${$('#composition-changes').innerHTML}<h2>Medidas registradas</h2><table>${$('#comparison table').innerHTML}</table><h2>Gráfico de ${esc(fields[$('#metric').value][0])}</h2><p>Filtro: ${esc($('#chart-range').selectedOptions[0].textContent)}.</p><div class="report-chart">${$('#chart').innerHTML}</div><h2>Contexto e observações</h2>${getRecords().filter(r=>r.date>=a.date&&r.date<=b.date).map(r=>`<h3>${date(r.date)}</h3><p>${esc(contextLabel(r))||'Contexto não informado.'}</p><p>${esc(r.notes)||'Sem observações.'}</p>`).join('')}<p>BF e composição são estimativas. Massa livre de gordura não equivale a massa muscular. Este relatório descreve os dados registrados e não substitui uma avaliação profissional.</p>`;report.hidden=false;window.print();report.hidden=true;};
  return {refresh,load,reset(){epoch++;saving=false;preferences=emptyPreferences();revision=0;photos=[];clearPhotoViews();$('#photo-form').reset();$('#photo-form').elements.date.value=today();$('#goal-form').reset();for(const k of ['a','b'])$('#photo-'+k).innerHTML='';photoStatus('');status('');report.replaceChildren();setTab('summary');refresh();},open:record=>wizard.open(record),context:()=>wizard.context(),compare:renderRegion,review(record){const changes=unusualChanges(record,getRecords());return !changes.length||confirm('Confira estas mudanças acima de 20% em relação à avaliação anterior:\n\n'+changes.map(c=>`${fields[c.key][0]}: ${fmt(c.before)} → ${fmt(c.after)} ${fields[c.key][1]}`).join('\n')+'\n\nEste é um aviso de conferência, não um limite clínico. Manter os valores e salvar?');},filterChart(records){const mode=$('#chart-range').value;if(mode==='all')return records;const all=getRecords();if(mode==='selected'){const a=all.find(r=>r.id===$('#from').value),b=all.find(r=>r.id===$('#to').value);return a&&b?records.filter(r=>r.date>=a.date&&r.date<=b.date):[];}const end=all.at(-1)?.date;return end?records.filter(r=>days(r.date,end)<=Number(mode)):[];}};
}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function imageData(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15000000)throw Error('Escolha uma imagem JPEG, PNG ou WebP de até 15 MB.');const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>50000000)throw Error('Imagem muito grande. Reduza a resolução antes de enviar.');const scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);let quality=.85,data;do{data=canvas.toDataURL('image/jpeg',quality);quality-=.1;}while(data.length>1350000&&quality>.3);if(data.length>1350000)throw Error('Reduza a imagem e tente novamente. Limite final de 1 MB.');return data;}finally{bitmap.close();}}
